-- Schema for the painting catalogue. Applied in every environment by Flyway, in version order (V1, V2, ...).
-- Never edit a migration that has already run somewhere: Flyway stores a checksum and would refuse to start.
-- To change the schema, add a new versioned file instead.
CREATE TABLE paintings (
    -- Generated by the database; the API never lets clients choose it.
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title       VARCHAR(150)  NOT NULL,
    artist      VARCHAR(120)  NOT NULL,
    description VARCHAR(2000),                 -- optional
    -- Exact decimal (12 digits, 2 after the point); money must never be stored as a floating-point number.
    price       NUMERIC(12,2) NOT NULL,
    stock       INTEGER       NOT NULL,        -- 0 means sold out
    image_url   VARCHAR(1000),                 -- optional link to a picture
    -- Last line of defence: even if application validation were bypassed, bad data cannot be stored.
    CONSTRAINT chk_paintings_price CHECK (price >= 0.01),
    CONSTRAINT chk_paintings_stock CHECK (stock >= 0)
);
